import { cn } from '@/lib/cn';
import { BRAND_INK, BRAND_THREADS } from '@/theme/brand';

const [AGENTS, IDENTITY, GOVERNANCE] = BRAND_THREADS;

/**
 * The app mark: three lines of writing, one per pillar, on blue-black ink.
 * Matches public/favicon.svg (generated by scripts/generate-icons.mjs).
 */
export function BrandMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 512 512" aria-hidden="true" focusable="false" className={cn('size-6 shrink-0', className)}>
      <rect width="512" height="512" rx="112" fill={BRAND_INK} />
      <rect x="112" y="148" width="288" height="56" rx="28" fill={AGENTS} />
      <rect x="112" y="228" width="224" height="56" rx="28" fill={IDENTITY} />
      <rect x="112" y="308" width="160" height="56" rx="28" fill={GOVERNANCE} />
    </svg>
  );
}
